"""Tenant/run-scoped, append-only evaluation evidence."""

import copy

from .store import JsonStore, identifier, integer
from .economics import summarize


class Ledger:
    def __init__(self, path):
        self.store = JsonStore(path)

    @staticmethod
    def _run(data, tenant, run_id):
        identifier(tenant)
        identifier(run_id)
        try:
            return data[tenant][run_id]
        except KeyError:
            raise ValueError('unknown run') from None

    def register_run(self, tenant, run_id, revision, task_ids, primary_metric):
        for value in (tenant, run_id, revision, primary_metric):
            identifier(value)
        if not isinstance(task_ids, list) or not 1 <= len(task_ids) <= 1000:
            raise ValueError('tasks required')
        for task in task_ids:
            identifier(task)
        if len(set(task_ids)) != len(task_ids):
            raise ValueError('duplicate task')
        pin = dict(revision=revision, task_ids=copy.deepcopy(task_ids), primary_metric=primary_metric)

        def action(data):
            # Nested keys keep arbitrary separators in identifiers unambiguous.
            runs = data.setdefault(tenant, {})
            if run_id in runs:
                if any(runs[run_id][key] != value for key, value in pin.items()):
                    raise ValueError('pin conflict')
                return False
            runs[run_id] = dict(**pin, operations={}, completed=[], reviews={}, retractions={})
            return True

        return self.store.transact(action)

    def _record(self, tenant, run_id, record, category):
        if not isinstance(record, dict):
            raise ValueError('record required')
        if category == 'operations':
            fields = {'id', 'task_id', 'kind', 'invoked', 'replay', 'status', 'cost_microusd'}
            if set(record) != fields:
                raise ValueError('operation shape')
            if (record['kind'] not in ('workflow', 'judge')
                    or record['status'] not in ('succeeded', 'failed')):
                raise ValueError('operation enum')
            if type(record['invoked']) is not bool or type(record['replay']) is not bool:
                raise ValueError('operation flags')
            if record['cost_microusd'] is not None:
                integer(record['cost_microusd'])
        else:
            fields = {'id', 'task_id', 'metric_revision', 'status', 'sequence', 'passed'}
            if set(record) != fields:
                raise ValueError('review shape')
            identifier(record['metric_revision'])
            integer(record['sequence'], high=1_000_000)
            if record['status'] == 'completed':
                if type(record['passed']) is not bool:
                    raise ValueError('completed passed')
            elif record['status'] == 'pending':
                if record['passed'] is not None:
                    raise ValueError('pending passed')
            else:
                raise ValueError('review status')
        identifier(record['id'])
        identifier(record['task_id'])
        record = copy.deepcopy(record)

        def action(data):
            run = self._run(data, tenant, run_id)
            if record['task_id'] not in run['task_ids']:
                raise ValueError('unknown task')
            records = run[category]
            if record['id'] in records:
                if records[record['id']] != record:
                    raise ValueError('record conflict')
                return False
            records[record['id']] = record
            return True

        return self.store.transact(action)

    def record_operation(self, tenant, run_id, operation):
        return self._record(tenant, run_id, operation, 'operations')

    def record_review(self, tenant, run_id, review):
        return self._record(tenant, run_id, review, 'reviews')

    def retract_review(self, tenant, run_id, review_id, retraction_id, reason):
        """Append a receipt without changing or releasing the review's identity."""
        identifier(review_id)
        identifier(retraction_id)
        if not isinstance(reason, str) or not 1 <= len(reason) <= 500:
            raise ValueError('invalid retraction reason')
        receipt = dict(id=retraction_id, review_id=review_id, reason=reason)

        def action(data):
            run = self._run(data, tenant, run_id)
            if review_id not in run['reviews']:
                raise ValueError('unknown review')
            # Stage-0 stores may lack this collection. Initialize it only in a
            # successful transaction; reading an older store never rewrites it.
            receipts = run.setdefault('retractions', {})
            if retraction_id in receipts:
                if receipts[retraction_id] != receipt:
                    raise ValueError('retraction conflict')
                return False
            receipts[retraction_id] = receipt
            return True

        return self.store.transact(action)

    def complete_task(self, tenant, run_id, task_id):
        identifier(task_id)

        def action(data):
            run = self._run(data, tenant, run_id)
            if task_id not in run['task_ids']:
                raise ValueError('unknown task')
            if task_id in run['completed']:
                return False
            run['completed'].append(task_id)
            return True

        return self.store.transact(action)

    def snapshot(self, tenant, run_id):
        run = self._run(self.store.data, tenant, run_id)
        return copy.deepcopy(dict(
            revision=run['revision'],
            task_ids=run['task_ids'],
            primary_metric=run['primary_metric'],
            operations=list(run['operations'].values()),
            completed=sorted(run['completed']),
            reviews=list(run['reviews'].values()),
            retractions=list(run.get('retractions', {}).values()),
        ))

    def summary(self, tenant, run_id):
        return summarize(self._run(self.store.data, tenant, run_id))
